pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        bound(amount, 0, 2); // keep 0 (and small values) reachable
        Reverter r = new Reverter(); // adversarial receiver that rejects transfers

        bool ok; // ok = call succeeded OR reverted with a standard require-style Error(string)
        vm.prank(address(this)); // test contract is the owner of c
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch Error(string memory) {
            ok = true; // require-style revert (empty-string require reverts match here)
        } catch {
            ok = false; // revert from a failed low-level transfer / panic
        }

        // Universal rule: for a receiver that rejects transfers, P reverts with an
        // Error(string) exactly when amount == 0 (pre-transfer require fires first),
        // otherwise the transfer itself fails. The mutant moves the require after the
        // transfer, so amount == 0 reverts via the failed transfer (generic catch).
        assertTrue(ok == (amount == 0));
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

