import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        bound(amount, 0, type(uint128).max);
        // adversarial receiver that rejects any transfer
        Reverter r = new Reverter();
        // owner of c is address(this) (deployer in setUp)
        bool stringErr = false;
        vm.prank(address(this));
        try c.sendTo(address(r), amount) {
            stringErr = false;
        } catch Error(string memory) {
            stringErr = true;
        } catch {
            stringErr = false;
        }
        // General rule: whenever sendTo reverts for amount == 0, it must be a
        // require-style Error(string) revert (the amount check precedes the transfer).
        assertTrue(amount > 0 || stringErr);
    }
}

