pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = msg.sender;
    }

    function testFuzz_property(uint256 amount) public {
        Recv rcv = new Recv();
        vm.assume(amount == 0 || amount <= address(c).balance + 1 ether);
        vm.deal(address(c), 1 ether);
        vm.deal(owner, 0);
        vm.prank(owner);
        bool ok;
        try c.sendTo(address(rcv), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: any sendTo call that reverts must not have delivered a transfer
        // to the receiver. P reverts on amount == 0 before any transfer; M
        // transfers (counting the delivery) and only then reverts.
        assertTrue(ok || rcv.count() == 0);
    }
}

contract Recv {
    uint256 public count;
    receive() external payable {
        count++;
    }
}

