pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address receiver, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(receiver != address(0));
        // adversarial counterparty: a receiver that reverts WITH data (so a
        // bubbled low-level transfer revert is distinguishable from P's empty require revert)
        Reverter rcv = new Reverter();
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool revertedWithData;
        try c.sendTo(address(rcv), amount) {
            revertedWithData = false;
        } catch (bytes memory returndata) {
            revertedWithData = returndata.length > 0;
        }
        // Rule: any revert of sendTo must carry NO revert data (plain requires only).
        // P: always empty revert data. M: with amount==0 it calls transfer first,
        // which bubbles the receiver's non-empty revert string.
        assertTrue(!revertedWithData);
    }
}

contract Reverter {
    fallback() external payable {
        revert("reject transfer");
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address receiver, uint amount) public {
        require(receiver != address(0));
        require(amount > 0);
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSelector(c.sendTo.selector, receiver, amount));
        assert(!ok);
    }
}

