contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address receiver, uint amount) public {
        require(receiver != address(0));
        require(amount > 0);

        uint balBefore = address(c).balance;

        bool ok;
        (ok, ) = address(c).call(
            abi.encodeWithSelector(C.sendTo.selector, receiver, amount)
        );

        uint balAfter = address(c).balance;

        // A call that reverts must leave the balance unchanged, and
        // an arbitrary (non-owner) caller must not be able to make it succeed.
        assert(!ok && balAfter == balBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

